class TeistroContext:
    """A live context, and every call that takes one.

    The handle is freed by `close`, by leaving a `with` block, or by the
    finaliser when neither happened; a result that waits for the
    collector can exhaust memory (ADR-0007, finding 4), so the explicit
    forms are the ones to use.
    """

    def __init__(
        self, lib: TeistroLibrary, handle: "ctypes._Pointer[_Context]"
    ) -> None:
        self._lib = lib
        self._handle: Optional["ctypes._Pointer[_Context]"] = handle
        self._finalise = weakref.finalize(self, _free_context, lib, handle)

    @classmethod
    def _new(cls, lib: TeistroLibrary, options: ContextOptions, provider: Any) -> TeistroContext:
        """Creates a context. `options` may be null for every default; `provider`
        may be null, in which case the `TS_CONTEXT_TEST_PROVIDER` flag selects
        the analytic test provider and no flag leaves the context without an
        ephemeris (positions are then `CAPABILITY`); `provider_user_data` is
        passed back to the vtable's functions untouched and must stay valid
        until `ts_context_free`. On success `*out_context` owns the context;
        on failure, when `out_error` is not null, it receives the error's
        message as a string to free with `ts_string_free`.
        """
        owned: list[Any] = []
        handle = ctypes.POINTER(_Context)()
        _options = options._to_c(owned)
        _out_error = _StringStruct()
        status = Status(lib.ts_context_new(
            ctypes.byref(_options),
            provider,
            None,
            ctypes.byref(handle),
            ctypes.byref(_out_error),
        ))
        if status != Status.OK:
            _refuse(lib, status, _out_error)
        return cls(lib, handle)

    @property
    def _raw(self) -> "ctypes._Pointer[_Context]":
        """The live handle, or a refusal saying it was closed."""
        if self._handle is None:
            raise TeistroError(
                Status.INVALID_ARG,
                "this context has been closed",
                hint="open another one",
            )
        return self._handle

    def close(self) -> None:
        """Frees the context's native memory. Closing twice is allowed."""
        if self._handle is not None:
            self._handle = None
            self._finalise()

    def __enter__(self) -> TeistroContext:
        return self

    def __exit__(
        self,
        kind: Optional[type[BaseException]],
        value: Optional[BaseException],
        traceback: Optional[TracebackType],
    ) -> None:
        self.close()

    def _raise(self, status: Status) -> None:
        """Raises what the library said about its last refusal."""
        raw = _ErrorStruct()
        raw.struct_size = ctypes.sizeof(_ErrorStruct)
        if self._handle is not None:
            if self._lib.ts_context_last_error(self._handle, ctypes.byref(raw)) == 0:
                found = Error._of(raw)
                raise TeistroError(
                    status,
                    found.message or status.key,
                    detail=found.detail or "",
                    field=found.field or "",
                    hint=found.hint or "",
                    key=found.key or "",
                )
        raise TeistroError(status, status.key)

    def last_error(self) -> Error:
        """The outcome of the last call on the context: its status, the provider's
        code, and the message, field, hint and key as strings lent until the
        next call other than this one. After a successful call the record is
        `OK` with a null message.
        """
        _out_error = _ErrorStruct()
        _out_error.struct_size = ctypes.sizeof(_ErrorStruct)
        status = Status(self._lib.ts_context_last_error(
            self._raw,
            ctypes.byref(_out_error),
        ))
        if status != Status.OK:
            self._raise(status)
        error = Error._of(_out_error)
        return error

