def _free_context(lib: TeistroLibrary, handle: Any) -> None:
    """The finaliser: frees a handle whoever let it go."""
    if handle:
        lib.ts_context_free(handle)


def abi_version(lib: TeistroLibrary) -> int:
    """The ABI version this library implements."""
    value = lib.ts_abi_version()
    value = int(value)
    return value


def sdk_version(lib: TeistroLibrary) -> str:
    """The SDK version as a static NUL-terminated string (`0.0.0`)."""
    value = lib.ts_sdk_version()
    return _text(value)


def catalogue_version(lib: TeistroLibrary) -> int:
    """The catalogue schema version every result's provenance stamps."""
    value = lib.ts_catalogue_version()
    value = int(value)
    return value


def default_profile(lib: TeistroLibrary) -> str:
    """The profile a context uses when its options name none, as a static
    NUL-terminated string.
    """
    value = lib.ts_default_profile()
    return _text(value)


def build_info(lib: TeistroLibrary) -> str:
    """What this build is, as a static NUL-terminated JSON object: the SDK
    version, the ABI and catalogue versions, the commit and whether its
    tree was clean, the profile, the target, whether debug assertions and
    optimisation are on, the sanitizer if any, and the compiler.

    A binding reads it when it loads the library and refuses one that is
    not the build its own half was generated for
    (`02-architecture/07-binding-architecture.md`, "Loading and
    identity"). The document is written when the library is compiled, so
    it costs nothing to ask and cannot disagree with the library it
    describes.
    """
    value = lib.ts_build_info()
    return _text(value)


def status_message(lib: TeistroLibrary, status: Status) -> str:
    """A static NUL-terminated English phrase for a status code; `unknown
    status` for a code this build does not know.
    """
    value = lib.ts_status_message(_c_value(status))
    return _text(value)


def frame_canonical(lib: TeistroLibrary) -> Frame:
    """Writes the SDK's canonical frame: apparent geocentric ecliptic of date,
    tropical, which both licensed engines return by default and every chart
    module consumes. Set `struct_size` before the call.
    """
    _out_frame = _FrameStruct()
    _out_frame.struct_size = ctypes.sizeof(_FrameStruct)
    status = Status(lib.ts_frame_canonical(ctypes.byref(_out_frame)))
    if status != Status.OK:
        _refuse(lib, status, None)
    frame = Frame._of(_out_frame)
    return frame


def frame_pack(lib: TeistroLibrary, frame: Frame) -> int:
    """Packs a frame into the bits a position request carries."""
    owned: list[Any] = []
    _frame = frame._to_c(owned)
    _out_bits = ctypes.c_uint32()
    status = Status(lib.ts_frame_pack(
        ctypes.byref(_frame),
        ctypes.byref(_out_bits),
    ))
    if status != Status.OK:
        _refuse(lib, status, None)
    owned.clear()
    bits = _out_bits.value
    return bits


def frame_unpack(lib: TeistroLibrary, bits: int) -> Frame:
    """Reads packed frame bits back into their fields; bits no frame sets are
    `INVALID_ARG`.
    """
    _out_frame = _FrameStruct()
    _out_frame.struct_size = ctypes.sizeof(_FrameStruct)
    status = Status(lib.ts_frame_unpack(
        _c_value(bits),
        ctypes.byref(_out_frame),
    ))
    if status != Status.OK:
        _refuse(lib, status, None)
    frame = Frame._of(_out_frame)
    return frame


def calendar_jd_of_fixed(lib: TeistroLibrary, fixed: int) -> float:
    """The Julian day at the UTC midnight that begins a fixed day (fixed day
    1 is Monday, 1 January 1 CE; the relation is `fixed + 1721424.5`).
    """
    value = lib.ts_calendar_jd_of_fixed(_c_value(fixed))
    value = float(value)
    return value


def calendar_fixed_of_jd(lib: TeistroLibrary, jd: float) -> CalendarFixedOfJdResult:
    """The fixed day a Julian day falls in, and, when `out_fraction` is not
    null, the fraction of that day elapsed since its midnight.
    """
    _out_fraction = ctypes.c_double()
    value = lib.ts_calendar_fixed_of_jd(
        _c_value(jd),
        ctypes.byref(_out_fraction),
    )
    value = int(value)
    fraction = _out_fraction.value
    return CalendarFixedOfJdResult(value=value, fraction=fraction)


def _refuse(lib: TeistroLibrary, status: Status, detail: Any) -> None:
    """Raises a refusal from a call with no context to ask.

    `detail` is the owned string such a call fills when it has more to
    say than a code, which is freed here whether or not it is used.
    """
    said = "" if detail is None else _take_string(lib, detail)
    raise TeistroError(
        status, said or _text(lib.ts_status_message(int(status)))
    )


def _take_string(lib: TeistroLibrary, raw: Any) -> str:
    """A string the library allocated, copied out and freed."""
    if not raw.data:
        return ""
    text = ctypes.string_at(raw.data, raw.len).decode("utf-8")
    lib.ts_string_free(ctypes.byref(raw))
    return text


def _take_blob(lib: TeistroLibrary, raw: Any) -> bytes:
    """A result blob the library allocated, copied out and freed.

    One copy rather than none, deliberately: a decoded column is a view
    over these bytes, and a view over the library's own memory would read
    freed memory the moment the blob was let go.
    """
    if not raw.data:
        return b""
    blob = ctypes.string_at(raw.data, raw.len)
    lib.ts_blob_free(ctypes.byref(raw))
    return blob
